from hypothesis import strategies as st

MOD = 998244353

@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    a = draw(st.lists(st.integers(-3, 3), min_size=n, max_size=n))
    k = draw(st.integers(-4, 4))
    return f"{n} {k}\n{' '.join(map(str, a))}\n"

def validate(inp):
    t = inp.split()
    if len(t) < 2:
        return False
    n, k = int(t[0]), int(t[1])
    a = [int(x) for x in t[2:]]
    return (1 <= n <= 2 * 10**5
            and -10**15 <= k <= 10**15
            and len(a) == n
            and all(-10**9 <= x <= 10**9 for x in a))

def ref(inp):
    t = inp.split()
    n, k = int(t[0]), int(t[1])
    a = [int(x) for x in t[2:2 + n]]
    count = 0
    # Enumerate all 2^(n-1) ways to cut the array into contiguous parts.
    for mask in range(1 << (n - 1)):
        ok = True
        start = 0
        for i in range(n):
            # a cut after position i if bit i is set (for i < n-1)
            if i == n - 1 or (mask >> i) & 1:
                if sum(a[start:i + 1]) == k:
                    ok = False
                    break
                start = i + 1
        if ok:
            count += 1
    return str(count % MOD)
