    k = draw(st.one_of(st.integers(-6, 6), st.just(0)))
    return f"{n} {k}\n{' '.join(map(str, a))}\n"

def validate(inp):
    try:
        lines = inp.strip("\n").split("\n")
        if len(lines) != 2:
            return False
        first = lines[0].split()
        if len(first) != 2:
            return False
        n, k = int(first[0]), int(first[1])
        a_tokens = lines[1].split()
        if len(a_tokens) != n:
            return False
        a = [int(x) for x in a_tokens]
    except ValueError:
        return False
    return (1 <= n <= 2 * 10**5
            and -10**15 <= k <= 10**15
            and all(-10**9 <= x <= 10**9 for x in a))

def ref(inp):
    lines = inp.strip("\n").split("\n")
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    count = 0
    # Enumerate all 2^(n-1) divisions: bit j set means a cut before element j+1 (0-indexed boundary j+1).
    for mask in range(1 << (n - 1)):
        segments = []
        start = 0
        for j in range(n - 1):
            if (mask >> j) & 1:
                segments.append(a[start:j + 1])
                start = j + 1
        segments.append(a[start:])
        ok = True
        for seg in segments:
            if sum(seg) == k:
                ok = False
                break
        if ok:
            count += 1
